for r in range(R):
 for c in range(C):
  if g[r][c]==3 or (r,c) in seen: continue
  col=g[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop(); cells.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
