     seen.add((nx,ny)); q.append((nx,ny))
  comps.append((col,min(x for x,y in cells),min(y for x,y in cells),max(x for x,y in cells),max(y for x,y in cells),len(cells),cells))
[(col,(r0,c0,r1,c1),n) for col,r0,c0,r1,c1,n,cells in comps]

